//! Independent Rust implementation of Open Layer Protocol Specifications 0003/0004.
//! Derived from the normative specifications and implementation-neutral vectors.
pub mod cbor;pub mod error;pub mod json;pub mod openssl_ed25519;pub mod proof;pub mod record;pub mod sha256;pub mod time;pub mod util;
use error::OlpError;use json::Json;
pub const CAPABILITIES:[&str;5]=["olp.record-identity.v1","olp.record-commitment.sha256.v1","olp.proof-input.v1","olp.proof.eddsa-ed25519.v1","olp.proof-verification.v1"];
pub fn execute(operation:&str,input:&Json)->Result<Json,OlpError>{match operation{"derive_record_identity"=>{let rec=input.get("record").map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?;record::identity_output(rec)},"derive_record_commitment"=>{let rec=input.get("record").map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?;let alg=input.get_opt("algorithm").map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?.map(|v|v.as_i64()).transpose().map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?.unwrap_or(-16);let c=proof::commitment(rec,alg)?;let mut o=Json::object();o.insert("algorithm".into(),Json::Int(c.algorithm as i128));o.insert("digest_hex".into(),Json::String(util::hex_encode(&c.digest)));Ok(Json::Object(o))},"encode_proof_input"=>proof::encode_input_operation(input),"create_proof"=>proof::create_operation(input),"verify_proof"=>proof::verify_operation(input),_=>Err(OlpError::unsupported("UNSUPPORTED_OPERATION",operation))}}
